select bt.id, bt.tariff_category_id as tariffCategoryId, btc.`name` as tariffCategoryName, btc.number as tariffCategoryNumber, bt.item_number as itemNumber, bt.`name`, bt.pinyin, bt.english_name as englishName, bt.unit, bt.price, bt.inservice from base_tariff bt left join base_tariff_category btc on bt.tariff_category_id = btc.id
and bt.id = #{queryForm.id}
and bt.tariff_category_id = #{queryForm.tariffCategoryId}
and CONCAT(IFNULL( bt.name, '' ), IFNULL( bt.item_number, '' ), IFNULL( bt.pinyin, '' )) like concat('%', #{queryForm.keyWord}, '%')
and bt.inservice = #{queryForm.inservice}

select bt.item_number as itemNumber, bt.`name`, btc.`name` as tariffCategoryName, btc.number as tariffCategoryNumber, bt.english_name as englishName, bt.unit, bt.price from base_tariff bt left join base_tariff_category btc on bt.tariff_category_id = btc.id
and bt.tariff_category_id = #{queryForm.tariffCategoryId}
and CONCAT(IFNULL( bt.name, '' ), IFNULL( bt.item_number, '' ), IFNULL( bt.pinyin, '' )) like concat('%', #{queryForm.keyWord}, '%')
and bt.inservice = #{queryForm.inservice}

select bt.id, bt.item_number as itemNumber, bt.`name`, bt.tariff_category_id as tariffCategoryId, btc.`name` as tariffCategoryName, btc.number as tariffCategoryNumber, bt.english_name as englishName, ifnull( bt.emr, '' ) as emr, ifnull( bt.attention, '' ) as attention, ifnull( group_concat(btfr.fellow_up), '' ) as fellowUp, bt.inservice from base_tariff bt left join base_tariff_category btc on bt.tariff_category_id = btc.id left join base_tariff_fellowup_relation btfr on btfr.base_tariff_id = bt.id
and bt.tariff_category_id = #{queryForm.tariffCategoryId}
and CONCAT(IFNULL( bt.name, '' ), IFNULL( bt.item_number, '' ), IFNULL( bt.pinyin, '' )) like concat('%', #{queryForm.keyWord}, '%')
and bt.inservice = #{queryForm.inservice}
group by bt.id

select bt.id, bt.item_number as itemNumber, bt.`name` as name, btc.`name` as tariffCategoryName, btc.number as tariffCategoryNumber, bt.english_name as englishName, ifnull( bt.emr, '' ) as emr, ifnull( bt.attention, '' ) as attention, ifnull( bt.fellow_up, '' ) as fellowUp from base_tariff bt left join base_tariff_category btc on bt.tariff_category_id = btc.id
and bt.tariff_category_id = #{queryForm.tariffCategoryId}
and CONCAT(IFNULL( bt.name, '' ), IFNULL( bt.item_number, '' ), IFNULL( bt.pinyin, '' )) like concat('%', #{queryForm.keyWord}, '%')
and bt.inservice = #{queryForm.inservice}

select
IF(item_number is null, '000', substr(MAX(item_number), -3, 3)) as maxnum
from base_tariff
where left(item_number, 3) = #{categoryNumber}
and tariff_category_id = #{tariffCategoryId};

select bt.id, bt.tariff_category_id as tariffCategoryId, btc.`name` as tariffCategoryName, '0' as tariffCategoryNumber, bt.item_number as itemNumber, bt.`name`, bt.pinyin, bt.english_name as englishName, bt.unit, bt.price, bt.inservice from base_tariff bt left join base_tariff_category btc on bt.tariff_category_id = btc.id
and bt.id = #{queryForm.id}
and bt.tariff_category_id = #{queryForm.tariffCategoryId}
and CONCAT(IFNULL( bt.name, '' ), IFNULL( bt.item_number, '' ), IFNULL( bt.pinyin, '' )) like concat('%', #{queryForm.keyWord}, '%')
and bt.inservice = #{queryForm.inservice}
union all select bot.id, bot.oral_tariff_category_id as tariffCategoryId, botc.`name` as tariffCategoryName, '1' as tariffCategoryNumber, bot.item_number as itemNumber, bot.`name`, bot.pinyin, bot.english_name as englishName, bot.unit, bot.price, bot.inservice from base_oral_tariff bot left join base_oral_tariff_category botc on bot.oral_tariff_category_id = botc.id
and bot.id = #{queryForm.id}
and bot.oral_tariff_category_id = #{queryForm.oralTariffCategoryId}
and CONCAT(IFNULL( bot.name, '' ), IFNULL( bot.item_number, '' ), IFNULL( bot.pinyin, '' )) like concat('%', #{queryForm.keyWord}, '%')
and bot.inservice = #{queryForm.inservice}

